import json
import os

from collections.abc import Callable
from dataclasses import dataclass


@dataclass
class Document:
    title: str
    text: str


class DocumentClassifier:
    """Classify documents using a connected LLM service."""

    __instance_cache: dict[tuple[tuple[str,str],...],"DocumentClassifier"] = {}

    @staticmethod
    def load_file_or_content(value: str) -> str:
        """
        Deal with a property that may be a filename or literal content.
        If it's a filename, load and return the file contents.
        """
        if os.path.isfile(value):
            with open(value, "r") as file:
                return file.read()
        return value

    @staticmethod
    def filter_properties(properties: dict[str,str], prefix: str, value_modifier: Callable[[str], str] = lambda x: x) -> dict[str,str]:
        """Return a new dictionary containing only properties with the given prefix."""
        if not prefix.endswith("."):
            prefix += "."
        return { k[len(prefix):]: value_modifier(v)
                    for k,v in properties.items() if k.startswith(prefix) }

    @classmethod
    def create_from_props(cls, properties: dict[str,str]) -> "DocumentClassifier":
        cache_key = tuple(sorted(properties.items()))
        cached = cls.__instance_cache.get(cache_key)
        if cached is None:
            cached = cls(properties)
            cls.__instance_cache[cache_key] = cached
        return cached

    @classmethod
    def _init_llmconnection(cls, connection_props: dict[str,str]) -> "LLMConnection":
        # Find name of the LLM connection class to use
        connection_type = connection_props.get("class", "OpenAIConnection")
        # Try to find class definition in llmconnection module
        import llmconnection
        if not (connection_cls := getattr(llmconnection, connection_type, None)):
            # Try to load it as a module
            from importlib import import_module
            if connection_module := import_module(connection_type.lower()):
                connection_cls = getattr(connection_module, connection_type, None)
        if not connection_cls:
            raise ImportError(f"LLM connection class {connection_type} not found")
        # Initialize the connection; filter properties to those with the right prefix
        return connection_cls.create(cls.filter_properties(
            connection_props, connection_cls.propertyPrefix, cls.load_file_or_content))


    def __init__(self, properties: dict[str,str]):
        # Initialize the connection
        self.llm_connection = self._init_llmconnection(self.filter_properties(properties, "connection"))
        # Load category definitions from JSON property
        if category_definitions := properties.get("category.definitions"):
            category_definitions = self.load_file_or_content(category_definitions)
            self.category_definitions = json.loads(category_definitions)["categories"]
        else:
            raise RuntimeError("No category definitions provided")
        self.categories = {name.lower():name for name in (cat["name"] for cat in self.category_definitions)}
        # Load prompt template from property or file
        if prompt_template := properties.get("prompt.template"):
            prompt_template = self.load_file_or_content(prompt_template)
            self.prompt_template = prompt_template
        else:
            raise RuntimeError("No prompt template provided")
        # Check expected placeholders in the prompt template
        for placeholder in ("{{categories}}", "{{text}}", "{{title}}"):
            if placeholder not in self.prompt_template:
                raise RuntimeError(f"Prompt template is missing required placeholder {placeholder}")

    def _build_prompt(self, document: Document) -> str:
        """Build the prompt to send to the LLM for the given document."""
        prompt = self.prompt_template
        prompt = prompt.replace("{{categories}}", json.dumps(self.category_definitions))
        prompt = prompt.replace("{{text}}", document.text)
        prompt = prompt.replace("{{title}}", document.title)
        return prompt

    def classify(self, document: Document) -> str|None:
        prompt = self._build_prompt(document)
        response = self.llm_connection.send_request(prompt)
        response = response.strip().lower()
        if response == "none":
            return None
        elif response in self.categories:
            return self.categories[response]
        else:
            raise RuntimeError(f"Unexpected category '{response}' returned by LLM")
